18	type ContainerState =
19		| "provisioning"
20		| "running"
21		| "failed"
22		| "stopping"
23		| "stopped"
24		| "unhealthy"
25		| "inactive"
26		| "unknown";
27	
28	function deriveInstanceState(
29		instance: DashApplicationInstance
30	): ContainerState {
31		const status = instance.current_placement?.status;
32		if (!status) {
33			return "unknown";
34		}
35	
36		const raw = status.container_status ?? status.health;
37		switch (raw) {
38			case "placed":
39				return "provisioning";
40			case "running":
41			case "failed":
42			case "stopping":
43			case "stopped":
44			case "unhealthy":
45				return raw;
46			default:
47				return "unknown";
48		}
49	}
50	
51	function colorState(state: ContainerState): string {
52		switch (state) {
53			case "running":
54				return green(state);
55			case "failed":
56			case "unhealthy":
57			case "stopped":
58			case "stopping":
59				return red(state);
60			default:
61				return state;
62		}
63	}
64	
65	type InstanceRow = {
66		instance?: DashApplicationInstance;
67		durableObject?: DashApplicationDurableObjectInstance;
68	};
69	
70	/**
71	 * Join instances with durable_objects data. When DO data is present,
72	 * DOs are correlated to instances via deployment_id. DOs without a
73	 * matching running instance are included with state "inactive".
74	 */
75	function buildInstanceRows(data: DashApplicationInstances): InstanceRow[] {
76		const doList = data.durable_objects ?? [];
77	
78		if (doList.length === 0) {
79			// Non-DO application: just return raw instances
80			return data.instances.map((instance) => ({ instance }));
81		}
82	
83		// Build a map from deployment_id -> instance for fast lookup
84		const instanceByDeploymentId = new Map<string, DashApplicationInstance>();
85		for (const inst of data.instances) {
86			instanceByDeploymentId.set(inst.id, inst);
87		}
88	
89		// Each DO is a row; join with matching instance if one exists
90		return doList.map((doInst) => ({
91			instance: doInst.deployment_id
92				? instanceByDeploymentId.get(doInst.deployment_id)
93				: undefined,
94			durableObject: doInst,
95		}));
96	}
