98	async function fetchPage(
99		applicationId: string,
100		perPage?: number,
101		pageToken?: string
102	): Promise<{
103		data: DashApplicationInstances;
104		nextPageToken?: string;
105	}> {
106		try {
107			const page = await ApplicationsService.listDashApplicationInstances(
108				applicationId,
109				perPage,
110				pageToken
111			);
112			return {
113				data: page.data,
114				nextPageToken: page.resultInfo?.next_page_token,
115			};
116		} catch (err) {
117			if (!(err instanceof Error)) {
118				throw err;
119			}
120	
121			if (err instanceof ApiError) {
122				if (err.status === 400 || err.status === 404) {
123					throw new UserError(
124						`There has been an error fetching instances.\n${err.body.error}\nUse \`wrangler containers list\` to view your containers and corresponding IDs.`
125					);
126				}
127	
128				throw new Error(
129					`There has been an unknown error fetching instances.\n${JSON.stringify(err.body)}`
130				);
131			}
132	
133			throw new Error(
134				`There has been an internal error fetching instances.\n${err.message}`
135			);
136		}
137	}
